sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float levels;

half4 main(float2 coord) {
    half4 col = image.eval(coord);
    if (col.a < 1e-3) {
        return half4(0);
    }

    half3 rgb = col.rgb / col.a;

    half lv = levels - 1.0;

    half r = floor(rgb.r * lv) / lv;
    half g = floor(rgb.g * lv) / lv;
    half b = floor(rgb.b * lv) / lv;

    return half4(half3(r, g, b) * col.a, col.a);
}
